SELECT

FROM question q
JOIN question_bank b ON b.id = q.bank_id

    AND q.bank_id = #{bankId}
    AND q.type = #{type}
    AND q.stem LIKE CONCAT('%', #{keyword}, '%')
    AND q.difficulty = #{difficulty}

        AND EXISTS (SELECT 1 FROM question_tag qt WHERE qt.question_id = q.id AND qt.tag_id = #{tagId})


ORDER BY q.bank_id, q.sort_no, q.id

SELECT id FROM question
WHERE bank_id = #{bankId} AND type = #{type}
ORDER BY RAND()
LIMIT #{limit}
